}

.kpi-meta {
  font-size: 0.78rem;
  color: var(--theme-on-surface-variant);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.data-row.editing-active {
  border-color: var(--amber-primary);
  background: var(--amber-container);
}

@media (max-width: 980px) {
