3: /**
4:  * Representa valores monetários em centavos inteiros (Martin Fowler, Money Pattern),
5:  * eliminando erros de ponto flutuante IEEE 754 no cálculo de orçamentos.
6:  */
7: export class Money {
8:   public readonly cents: number;
9: 
10:   private constructor(cents: number) {
11:     this.cents = cents;
12:   }
13: 
14:   public static zero(): Money {
15:     return new Money(0);
16:   }
17: 
18:   public static fromPositiveCents(cents: number): Money {
19:     if (!Number.isInteger(cents) || cents <= 0) {
20:       throw new DomainValidationError('O valor em centavos deve ser um número inteiro maior que zero.');
21:     }
22:     return new Money(cents);
23:   }
24: 
25:   public static fromNonNegativeCents(cents: number): Money {
26:     if (!Number.isInteger(cents) || cents < 0) {
27:       throw new DomainValidationError('O valor em centavos não pode ser negativo.');
28:     }
29:     return new Money(cents);
30:   }
31: 
32:   public static fromPositiveDecimal(amount: number): Money {
33:     if (!Number.isFinite(amount) || amount <= 0) {
34:       throw new DomainValidationError('O preço deve ser maior que zero.');
35:     }
36:     const cents = Math.round(amount * 100);
37:     if (cents <= 0) {
38:       throw new DomainValidationError('O preço deve ser maior que zero.');
39:     }
40:     return new Money(cents);
41:   }
42: 
43:   public add(other: Money): Money {
44:     return new Money(this.cents + other.cents);
45:   }
46: 
