48:     if (!Number.isFinite(quantity) || quantity <= 0) {
49:       throw new DomainValidationError('A quantidade multiplicadora deve ser maior que zero.');
50:     }
51:     return new Money(Math.round(this.cents * quantity));
52:   }
53: 
54:   public toDecimal(): number {
55:     return Number((this.cents / 100).toFixed(2));
