{"function":"async () => {
  await quickLogin('marcos.paulista', 'Oficina@2026!');
  await navigateRoute('/oficina');

  const pillCounts = Array.from(document.querySelectorAll('#prod-subtype-pills .subtype-pill')).map(b => b.textContent.trim());

  // Filter by 'OLEO:FREIO' (9 products for 3 brake catalogs)
  setProductSubtypeFilter('OLEO:FREIO');
  const brakeCardsCount = document.querySelectorAll('#oficina-products-list .product-item-card').length;
  setProductSubtypeFilter('ALL');

  // Check custom select search on #prod-catalog-select
  const catSelect = document.getElementById('prod-catalog-select');
  const catWrapper = catSelect.closest('.custom-select-wrapper');
  const catTrigger = catWrapper.querySelector('.custom-select-trigger');
  catTrigger.click();
  const hasSearchInput = !!catWrapper.querySelector('.custom-select-search-input');
  closeAllCustomSelectMenus();

  // Check Client Portfolio last quoted vehicle badges
  const clientCardsText = document.getElementById('oficina-clients-list').innerText;

  // Test 1-click "Cotar Toyota Corolla ->" shortcut for Fernanda Ribeiro
  await quoteClientLastVehicle(2, 5);
  const drawerOpen = document.getElementById('quote-drawer').classList.contains('open');
  const drawerItemsText = document.getElementById('drawer-items-list').innerText;

  // Test toggling bottle rounding from exact 4.3L to 5 bottles of 1L
  toggleQuoteOilBottleRounding();
  const drawerItemsRoundedText = document.getElementById('drawer-items-list').innerText;

  return {
    pillCounts,
    brakeCardsCount,
    hasSearchInput,
    clientCardsText,
    drawerOpen,
    drawerItemsText,
    drawerItemsRoundedText,
  };
}"}

